import React, { useState } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { GoogleSignInButton } from './GoogleSignInButton';
import { Tv, FolderGit2, Shield, Sparkles, Mail, Lock, ArrowRight, Loader2 } from 'lucide-react';
import { OnboardingModal } from './OnboardingModal';

export const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user, loading, spaces, createSpace, signInWithPassword, signUpWithPassword } = useAuth();
  const [isCreatingSpace, setIsCreatingSpace] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (loading) {
    return (
      <div className="min-h-screen bg-tv-bg flex flex-col items-center justify-center p-4">
        <div className="w-12 h-12 rounded-full border-4 border-tv-cyan/30 border-t-tv-cyan animate-spin mb-4" />
        <p className="text-tv-textMuted text-sm">Connecting to Family File Library...</p>
      </div>
    );
  }

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setAuthError('Please enter both email and password.');
      return;
    }
    if (password.length < 6) {
      setAuthError('Password must be at least 6 characters.');
      return;
    }

    setAuthError(null);
    setIsSubmitting(true);
    try {
      if (isSignUp) {
        await signUpWithPassword(email.trim(), password);
      } else {
        await signInWithPassword(email.trim(), password);
      }
    } catch (err: any) {
      console.error('[Auth Error]', err);
      // If user doesn't exist when signing in, suggest creating account
      if (err.message?.includes('Invalid login credentials') && !isSignUp) {
        setAuthError('Invalid credentials. If this is your first time, click "Create Account" below.');
      } else {
        setAuthError(err.message || 'Authentication failed. Please check your credentials.');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-tv-bg flex flex-col items-center justify-center p-4 relative overflow-hidden">
        {/* Ambient background glow */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-tv-cyan/10 rounded-full blur-3xl pointer-events-none" />

        <div className="max-w-md w-full bg-tv-card/90 backdrop-blur-md border border-tv-border rounded-2xl p-8 shadow-2xl relative z-10 text-center">
          <div className="w-16 h-16 bg-tv-elevated border border-tv-cyan/40 rounded-2xl mx-auto flex items-center justify-center shadow-lg shadow-tv-cyan/10 mb-4">
            <Tv className="w-8 h-8 text-tv-cyan" />
          </div>

          <h1 className="text-2xl font-bold text-tv-textLight tracking-tight mb-1">
            Family File Library
          </h1>
          <p className="text-tv-textMuted text-xs mb-6">
            Sign in to pair your TV and manage family files from any device
          </p>

          {/* Email / Password Form */}
          <form onSubmit={handleEmailAuth} className="space-y-3.5 mb-6 text-left">
            {authError && (
              <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-xl text-red-400 text-xs text-center">
                {authError}
              </div>
            )}

            <div>
              <label className="block text-xs font-medium text-tv-textMuted mb-1">Email Address</label>
              <div className="relative">
                <Mail className="w-4 h-4 text-tv-textMuted absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="email"
                  required
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-tv-bg/80 border border-tv-border rounded-xl pl-9 pr-3 py-2 text-sm text-tv-textLight placeholder-tv-textMuted/50 focus:outline-none focus:border-tv-cyan transition-colors"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-tv-textMuted mb-1">Password</label>
              <div className="relative">
                <Lock className="w-4 h-4 text-tv-textMuted absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-tv-bg/80 border border-tv-border rounded-xl pl-9 pr-3 py-2 text-sm text-tv-textLight placeholder-tv-textMuted/50 focus:outline-none focus:border-tv-cyan transition-colors"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-tv-cyan hover:bg-tv-cyan/90 text-slate-900 font-semibold py-2.5 px-4 rounded-xl flex items-center justify-center space-x-2 text-sm transition-all shadow-lg shadow-tv-cyan/20 disabled:opacity-50 mt-2"
            >
              {isSubmitting ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <>
                  <span>{isSignUp ? 'Create Free Account' : 'Sign In'}</span>
                  <ArrowRight className="w-4 h-4" />
                </>
              )}
            </button>

            <div className="text-center pt-1">
              <button
                type="button"
                onClick={() => {
                  setIsSignUp(!isSignUp);
                  setAuthError(null);
                }}
                className="text-xs text-tv-cyan hover:underline transition-all"
              >
                {isSignUp
                  ? 'Already have an account? Sign In'
                  : "New here? Click to Create Account (Instant)"}
              </button>
            </div>
          </form>

          {/* Divider */}
          <div className="relative flex py-2 items-center mb-4">
            <div className="flex-grow border-t border-tv-border"></div>
            <span className="flex-shrink mx-3 text-[11px] text-tv-textMuted uppercase tracking-wider">or</span>
            <div className="flex-grow border-t border-tv-border"></div>
          </div>

          <GoogleSignInButton className="w-full" />
        </div>
      </div>
    );
  }

  // If user has zero spaces, prompt onboarding space creation
  if (spaces.length === 0) {
    return (
      <div className="min-h-screen bg-tv-bg flex items-center justify-center p-4">
        <OnboardingModal
          isOpen={true}
          user={user}
          onSubmit={async (name) => {
            setIsCreatingSpace(true);
            try {
              await createSpace(name);
            } finally {
              setIsCreatingSpace(false);
            }
          }}
          isSubmitting={isCreatingSpace}
        />
      </div>
    );
  }

  return <>{children}</>;
};
